 guilds=[('white-thorn',7,'守路者的补给','Roadkeepers’ Supplies','检查下一趟自愿护送的补给，不替任何成员决定参不参加。','Check supplies for the next voluntary escort without deciding who must take part.','survey'),('nine-towers',25,'公开抄本的轮值','Open Copy Rotation','把获准公开的抄本整理清楚，不把封存私档一并放出。','Organize approved public copies without exposing sealed private records.','ledger'),('ashriver-league',1,'桥市的公秤','The Bridge Market Scale','在实际摊主见证下校准公秤，留下可复查的刻记。','Calibrate the shared scale before actual stallholders and leave checkable marks.','ledger'),('deephearth',20,'工伤药架','The Workers’ Medicine Shelf','按同工已同意的安排修好药架，不把药房变成某一家私库。','Repair the agreed medicine shelf without turning the clinic into one house’s private store.','forge'),('lostlands',44,'中转人的承诺','An Intermediary’s Promise','整理本人允许转告的联系请求，沉默不算同意。','Organize contact requests people have consented to relay; silence is not agreement.','parley')]
